CREATE TABLE T1 (
  C1 NUMBER PRIMARY KEY,
  C2 NUMBER NOT NULL,
  C3 NUMBER UNIQUE,
  C4 NUMBER CHECK (C4 IS NOT NULL)
);

-- ㉠
SELECT * FROM T WHERE ROWNUM = 1;
-- ㉡
SELECT * FROM T WHERE ROWNUM > 1;
-- ㉢
SELECT * FROM T WHERE ROWNUM <= 3;
-- ㉣
SELECT * FROM T
WHERE  ROWNUM BETWEEN 2 AND 3;

SELECT *
FROM   T1 A
WHERE  A.N1 NOT IN (SELECT B.N1 FROM T3 B);

-- (가)
SELECT SUM(NVL(COL1, 0) + NVL(COL2, 0)) FROM T;

-- (나)
SELECT NVL(SUM(COL1 + COL2), 0) FROM T;

-- (가)
SELECT COL1 FROM T WHERE COL1 IN ('A', 'B') OR COL2 <> 'c';

-- (나)
SELECT COL1 FROM T WHERE COL1 IN ('A', 'B')
UNION ALL
SELECT COL1 FROM T WHERE COL2 <> 'c';

-- (다)
SELECT COL1 FROM T WHERE COL1 IN ('A', 'B')
UNION
SELECT COL1 FROM T WHERE COL2 <> 'c';

-- (라)
SELECT COL1 FROM T WHERE COL1 = 'A' OR COL1 = 'B' OR COL2 <> 'c';

-- ㉠
SELECT N1 FROM SQLD WHERE 1 = 2;
-- ㉡
SELECT N1 FROM SQLD
WHERE  1 = 2 OR N1 IS NULL;
-- ㉢
SELECT N1 FROM SQLD
WHERE  NOT (N1 = 1);
-- ㉣
SELECT N1 FROM SQLD
WHERE  1 = 1 AND N1 > NULL;

SELECT 부서, 직급, AVG(급여)
FROM EMP
GROUP BY CUBE(부서, 직급);

-- ㉠
SELECT COUNT(*) FROM 직원, 급여등급;
-- ㉡
SELECT COUNT(*) FROM 직원
NATURAL JOIN 급여등급;
-- ㉢
SELECT COUNT(*) FROM 직원
CROSS JOIN 급여등급;
-- ㉣
SELECT COUNT(*) FROM 직원 E
JOIN 급여등급 G
  ON E.급여 BETWEEN G.하한
               AND G.상한;

